[
  {
    "url": "https://blog.stackademic.com/intersection-observer-api-the-right-way-to-detect-visibility-6e5a4babd07a",
    "title": "Intersection Observer API: The Right Way to Detect Visibility",
    "snippet": "The Intersection Observer API allows developers to detect when an element enters or leaves the viewport or a specific container element. Instead of continuously checking element positions manually, the browser efficiently monitors visibility changes and triggers a callback when specific conditions are met.",
    "published": null
  },
  {
    "url": "https://gomakethings.com/articles/how-to-detect-when-an-element-enters-or-leaves-the-viewport-with-vanilla-javascript/",
    "title": "How to detect when an element enters or leaves the viewport with ...",
    "snippet": "The Intersection Observer API can be used to observe and element and run a callback function when it enters or leaves the viewport (or another element). It runs asynchronously, and it’s far more performant than using a scroll event listener.",
    "published": null
  },
  {
    "url": "https://blog.openreplay.com/detect-elements-viewport-intersection-observer/",
    "title": "Detecting When Elements Enter the Viewport with Intersection Observer",
    "snippet": "Every scroll fires multiple events, each calling getBoundingClientRect () and forcing expensive browser reflows. The Intersection Observer API solves this problem elegantly, providing native browser optimization for detecting when elements enter or leave the viewport.",
    "published": null
  },
  {
    "url": "https://stackoverflow.com/questions/53306419/intersection-observer-when-element-leaves-the-viewport",
    "title": "Intersection Observer when element leaves the viewport",
    "snippet": "Is there a way to detect if an element leaves the viewport using Intersection Observers? For example, I have an element on the screen that I want to fire a callback when the top of the element hits the top of the viewport.",
    "published": null
  },
  {
    "url": "https://jsguides.dev/tutorials/browser-apis/browser-intersection-observer/",
    "title": "The Intersection Observer API for Viewport Detection",
    "snippet": "Learn how to detect when elements enter or leave the viewport using the Intersection Observer API for performant lazy loading and scroll-based features.",
    "published": null
  },
  {
    "url": "https://johnkavanagh.co.uk/articles/tracking-element-visibility-using-intersection-observer/",
    "title": "Track Element Visibility Using Intersection Observer",
    "snippet": "Historically, tracking an element's position within a user's viewport has been a complicated and arduous task of listening to scroll and resize events and then calculating an element's position using Element.getBoundingClientRect (). However, in the realm of modern web development, the Intersection Observer API stands out as a powerful tool for managing element visibility within the viewport ...",
    "published": null
  },
  {
    "url": "https://www.w3docs.com/learn-javascript/intersection-observer",
    "title": "JavaScript Intersection Observer API - W3docs",
    "snippet": "Learn the JavaScript Intersection Observer API to detect when an element enters or leaves the viewport — for lazy loading, infinite scroll, and animations.",
    "published": null
  },
  {
    "url": "https://web.dev/articles/intersectionobserver",
    "title": "IntersectionObserver's coming into view | Articles | web.dev",
    "snippet": "Making this visibility test more efficient is what IntersectionObserver was designed for, and it's landed in all modern browsers. IntersectionObserver lets you know when an observed element enters or exits the browser's viewport.",
    "published": null
  },
  {
    "url": "https://www.slingacademy.com/article/javascript-detect-when-a-div-goes-into-viewport/",
    "title": "JavaScript: Detect when a Div goes into viewport",
    "snippet": "One of the most efficient ways to detect if an element is in the viewport is by using the Intersection Observer API. This API provides a way to asynchronously observe changes in the intersection of a target element with an ancestor element or with a top-level document’s viewport.",
    "published": null
  },
  {
    "url": "https://www.xjavascript.com/blog/detect-whether-element-is-above-or-below-the-viewport-on-intersect-leave-with-intersection-observer/",
    "title": "How to Detect If an Element Is Above or Below the Viewport When Leaving ...",
    "snippet": "Enter the Intersection Observer API —a modern, performant solution for detecting when elements intersect with a viewport or another element. In this guide, we’ll dive deep into using Intersection Observer to detect when an element leaves the viewport and determine whether it’s moved above or below the visible area.",
    "published": null
  }
]
